    "5981": "إغلاق",
    "6227": "يحتاج الملف إلى تحليل AI ليتم تصنيفه، وسيكون هناك الكثير من الوقت إذا كان العدد كبيرًا، ووضع العمل يحدد ما إذا كانت نتائج التحليل مخزنة مؤقتًا على الخادم",
    "6229": "تحميل الدليل، والموارد الشبكية، والكتب الإلكترونية، والكوميكس، والموسيقى وغيرها من الملفات العامة.",
    "6230": "نتائج التحليل الخاصة بك تُحفظ محليًا فقط، ولا تُخزن مؤقتًا على الخادم، للحفاظ على سيادة البيانات. لكن لا يمكن الاستمتاع بتأثير تسريع ذاكرة التخزين المؤقتة للخادم.",
    "6231": "الأعمال الإبداعية الشخصية، والصور، والتقارير المالية، والمستندات الخاصة.",
    "6234": "منظم بالفعل، يتم تخطي التحليل. للتحليل الإلزامي، يرجى إنشاء دليل عمل مستقل.",
