    "7646": "فشلت ترقية قاعدة البيانات\\n\\nسبب الخطأ: {error}\\n\\nتم إجراء نسخ احتياطي لبياناتك الأصلية بشكل آمن إلى:\\n{path}\\n\\nالرجاء محاولة إعادة التشغيل، وسيقوم النظام تلقائيًا باستعادة النسخة الاحتياطية وإعادة الترقية.",
    "7647": "فشلت ترقية قاعدة البيانات",
    "7648": "إعادة تشغيل",
    "7649": "الخروج من التطبيق",
    "7650": "تم اكتشاف إصدار قديم من قاعدة البيانات (1.x.x)\\n\\nلم يعد الإصدار 2.0 من التطبيق يدعم ترقية قاعدة البيانات مباشرة من الإصدار القديم. \\n\\nالرجاء إجراء إحدى العمليات التالية:\\n1. قم بتثبيت الإصدار 1.3.2 وتشغيله أولاً لإكمال ترقية النقل، ثم قم بتثبيت الإصدار 2.0. \\n2. احذف ملف قاعدة البيانات القديم يدويًا (firefly-ai-folder.db) وأعد تشغيل التطبيق لإنشاء بنية 2.2 جديدة. \\n\\nسيتم إغلاق التطبيق الآن.",
