    "7685": "اعتبر دائمًا حماية الخصوصية مبدأً أساسيًا في التصميم والتزم به",
    "7686": "الأولوية المحلية للبيانات",
    "7687": "، لحماية خصوصية المستخدم وأمانه بشكل فعال، وتتوافق مبادئه التقنية الأساسية منطقيًا مع آلية التجزئة الشائعة (Hash) في الصناعة.",
    "7688": "بعبارات بسيطة",
    "7689": "سيقوم النظام بإنشاء معرف مميز فريد (الطول 16-128 حرفًا) لكل ملف من خلال خوارزمية تشفير، وهو ما يعادل المعرف الفريد للملف.",
    "7690": "قم بإنشاء هذا المعرف",
    "7691": "الفرضية الوحيدة",
    "7692": "، يحتفظ المستخدم بالملف محليًا ويكمل حساب الخوارزمية. لن يكشف التطبيق عن معرف الملف لأي طرف ثالث. فقط باستخدام هذا المعرف يمكن طلب بيانات التحليل الخاصة بالمعرف المقابل من الخادم، ولا توجد طريقة أخرى للحصول عليها.",
    "7693": "حتى في",
    "7694": "في ظل الافتراضات المتطرفة",
    "7695": "(تم اختراق الخادم)، ولا يمكن للأطراف الثالثة سوى الحصول على بيانات تحليل الملفات والمعرفات المقابلة، وتكون خوارزميات المعرفات الخاصة بالأنظمة الأساسية المختلفة مستقلة تمامًا وليس لها أي اتصال بمعرفات الملفات الخاصة بالأنظمة الأساسية مثل Baidu Netdisk، ولا يمكنها مطابقة الملفات الأصلية عبر الأنظمة الأساسية.",
    "7696": "في نفس الوقت،",
    "7697": "يقوم الخادم بتخزين البيانات التحليلية فقط",
    "7698": ": بما في ذلك أسماء الملفات الذكية، والعلامات، وملخصات المحتوى، والتقييمات والأسباب، والبيانات الوصفية، وما إلى ذلك، وهو ما يمكنك رؤيته في لوحة الخصائص على اليمين. لن يتم تحميل الملف نفسه أو تخزينه أبدًا.",
