    "7785": "حدث خطأ أثناء عملية التثبيت. يفتقد محرك الذكاء الاصطناعي الملفات الضرورية، مما يجعله يعمل في وضع التوافق. في الحالات الشديدة، قد تتعطل خدمة الذكاء الاصطناعي.",
