    "9794": "قم بالتسجيل واحصل على نسخة تجريبية بقيمة 10 دولارات، دون الحاجة إلى بطاقة ائتمان. الائتمان صالح في غضون 3 أشهر. تتضمن نماذج جامبا الكبيرة وجامبا ميني.",
    "9795": "إسرائيل",
    "9800": "علي بابا كلاود بيليان (النسخة الدولية)",
    "9801": "بعد التسجيل، سيحصل كل نموذج من نماذج Tongyi Qianwen على مليون رمز مجاني، صالح لمدة 90 يومًا (المنطقة الدولية/سنغافورة). لا حاجة لبطاقة الائتمان.",
    "9803": "مفتاح API \"تجريبي\" مجاني، لا حاجة لبطاقة ائتمان. 1000 مكالمة API شهريًا. للاستخدام غير التجاري فقط.",
    "9804": "كندا",
    "9816": "خطة \"تجريبية\" مجانية، لا تحتاج إلى بطاقة ائتمان. ما يقرب من 1 مليار الرموز شهريا. يمكن استخدام الكلمات الإرشادية لتحسين النموذج.",
    "9825": "زيبو آي",
    "9826": "يقدم نماذج مجانية إلى الأبد، لا حاجة لبطاقة الائتمان.",
    "9829": "مجانا، لا حاجة لبطاقة الائتمان. تفكير سريع للغاية (حوالي 2600 رمز/ثانية). الحد اليومي 1 مليون توكينز. حد سياق الملف المجاني 8K. من المقرر أن يتم إيقاف llama3.1-8b في 27 مايو 2026.",
    "9835": "10000 خلية عصبية مجانية كل يوم. يقدم الإصدار المجاني أكثر من 50 نموذجًا.",
    "9841": "أرصدة النماذج الأولية المجانية لجميع مستخدمي GitHub. تحتوي على أكثر من 45 موديل. يوجد حد للطلب الواحد (8K in / 4K out).",
    "9846": "مجانا، لا حاجة لبطاقة الائتمان. استنتاج LPU سريع للغاية.",
    "9851": "تزويد المستخدمين مجانًا بحصة خدمة استدلال شهرية تبلغ 100000 مرة. طرق إلى موفري الخدمة مثل Fireworks وTogether وHyperbolic وNebius وNovita وDeepInfra والمزيد. يدعم الآلاف من النماذج.",
    "9855": "نموذج مجاني، لا حاجة لبطاقة الائتمان. يتم توجيه `kilo-auto/free` تلقائيًا إلى minimax/minimax-m2.5:free (80%) وstepfun/step-3.5-flash:free (20%).",
    "9857": "بوابة API سلسة. لا يلزم التسجيل للوصول الأساسي. يدعم أكثر من 30 موديل. متوافقة مع اللائحة العامة لحماية البيانات.",
