    "9868": "قم بالتسجيل واحصل على رصيد مجاني بقيمة دولار واحد، دون الحاجة إلى بطاقة ائتمان. يتوفر أكثر من 60 نموذجًا مفتوح المصدر من خلال واجهة برمجة التطبيقات المتوافقة مع OpenAI. مقرها الرئيسي في الاتحاد الأوروبي.",
    "9869": "هولندا",
    "9872": "قم بالتسجيل واحصل على رصيد مجاني بقيمة 5 دولارات، دون الحاجة إلى بطاقة ائتمان. مزود سيادي للاتحاد الأوروبي مع مركز بيانات يقع في النرويج. لا حدود للمعدلات، ولا بداية باردة.",
    "9874": "مجاني مع حدود الاستخدام النوعية. يقدم أكثر من 400 نموذج من مكتبة أولاما. غير متوافق مع OpenAI SDK، استخدم [Ollama API](https://docs.olma.com/cloud).",
