    "19425": "المحرك الحالي هو محرك AI أساسي مدمج، يُنصح بتكوين محرك AI متطور، يمكن تعزيز نتائج التحليل بعد التكوين. انقر هنا للدخول إلى الإعدادات.",
    "19426": "المحرك الحالي هو محرك AI أساسي مدمج، يُنصح بتكوين محرك AI متطور، يمكن تعزيز نتائج التحليل بعد التكوين",
