    "19433": "بدأ التشغيل",
    "19434": "فشل بدء تشغيل محرك Firefly AI، يرجى فتح محرك Firefly AI يدويًا من قائمة البدء ثم إعادة المحاولة",
    "19435": "خدمة محليّة للذكاء الاصطناعي مدعومة بالمسرّات аппаратية وتُدعم من التطبيق مفتوح المصدر الذي طورته محرك Firefly AI، مع الاستخدام دون اتصال يضمن الخصوصية والأمان.",
    "19436": "الاتصال بخدمة ذكاء اصطناعي تابعة لطرف ثالث لتحليلها، مما يوفّر قدرات إدراك لغويّ أقوى، ويتطلّب حفظ الاتصال بالشبكة.",
