    "19579": "تفعيل البحث في الفيديو وتصحيح الوسوم (تصحيح عالي الأبعاد)",
    "19580": "بعد التفعيل، سيُجرى تصحيح عالي الأبعاد تلقائيًا بعد اكتمال تحليل قائمة الملفات: معايرة دقيقة للوسوم والتسمية الذكية باستخدام متجه متعدد الوسائط من 2048 بعدًا، وفتح إمكانية البحث عن الصور بناءً على الصور والبحث اللغوي الطبيعي في الفيديو.",
    "19581": "إجراء تصحيح متجهي عالي الأبعاد لوصف أسماء الملفات الذكية والوسوم للحصول على نتائج أكثر دقة، بالإضافة إلى دعم البحث الأذكى عن الملفات، بل يشمل البحث اللغوي الطبيعي عن محتوى الفيديو. بعد اكتمال تحليل قائمة الملفات، يتم إجراء التصحيح عالي الأبعاد تلقائيًا؛ يستغرق كل ملف حوالي ثانية واحدة.",
    "19582": "جاري اكتشاف نموذج التضمين متعدد الوسائط WeMM-Embedding 2B...",
