    "20516": "أمثلة: يجب ترجمة الاسم الذكي للملف إلى {activeLanguage}، الصيغة: المؤلف_وصف المحتوى. مثال: George Martin_A Game of Thrones.pdf. يتم توليد 20 علامة كحد أقصى، بحيث لا تتجاوز كل منها حرفين، ويجب استخراج علامة واحدة على الأقل من اسم الملف، بينما يجب استخراج البقية حصرياً من هذا المجموعة: [سعيد, متعذب, غاضب,...]",
    "20518": "تم تفعيلها",
    "20519": "يتطلب تفعيل محرك الذكاء الاصطناعي المتقدم",
    "20520": "كلمة تلميح مخصصة لضبط قواعد توليد التسميات والتصنيفات وتقييم الجودة",
    "20521": "محرك الذكاء الاصطناعي المتقدم غير مفعّل حاليًا، لذا كلمة التلميح غير فعّالة مؤقتًا",
    "20522": "كلمتا التلميح المخصّصتان لتقييم الجودة وتوليد الوسوم تعتمدان على قدرات نموذج اللغة في محرك الذكاء الاصطناعي المتقدم. سيتاح تفعيلهما بعد تفعيل محرك الذكاء الاصطناعي المتقدم.",
    "20523": "الانتقال لتفعيل محرك الذكاء الاصطناعي المتقدم",
    "20524": "تعليمات ضبط كلمات التلميح",
    "20525": "يوصى باستخدام نماذج سحابية ذات امتثال جيد أو نماذج ذات عدد كبير من المعلمات؛ وإذا كان فشل تحليل الذكاء الاصطناعي ناتجًا عن طول كلمة التلميح، يُرجى اختصار المحتوى بشكل مناسب. بالنسبة لنماذج الذكاء الاصطناعي المحلية الخفيفة، يُنصح بالاختصار إلى 100 حرف كحد أقصى.",
    "20526": "كلمات التلميح الخاصة بتقييم الجودة",
    "20527": "لم يتم تفعيل الذكاء الاصطناعي المتقدم",
    "20528": "تغيير تركيز وتروية منطق تقييم المحتوى متعدد الوسائط",
    "20529": "مسح",
    "20530": "لم يتم تفعيل محرك الذكاء الاصطناعي المتقدم، لذا لن تتسبب كلمات التلميح في أي تأثير حاليًا",
    "20531": "تم إعداد كلمات تلميح مخصصة",
    "20532": "اتركه فارغًا لاستخدام قالب كلمات التلميح الافتراضية",
    "20533": "حرف",
    "20534": "كلمات تلميح لإنشاء الملفات الذكية وأسماء الملفات",
    "20535": "إرشاد النموذج حول كيفية استخراج الكلمات المفتاحية وتنسيق أسماء الملفات واختيار التصنيفات",
    "20536": "سيتم حفظ أي تغييرات على كلمات التلميح لحظيًا باستخدام آلية المزامنة (Debounce)، وستتم تطبيقها على جميع مهام تحليل الملفات التي سيتم تشغيلها في المستقبل.",
    "20537": "تعتمد كلمات التلميح على قدرات نموذج اللغة الكبير في محرك الذكاء الاصطناعي المتقدم. بعد تفعيل محرك الذكاء الاصطناعي المتقدم، ستشارك هذه الإعدادات تلقائيًا في عملية التحليل.",
    "20538": "قدرات المحرك الأساسي المحفوظة",
    "20539": "يمكن فتحه عن طريق تفعيل المحرك المتقدم",
