    "20637": "1. الملفات المستوردة حديثاً: ستُستخرج الفهارس السيميائية مباشرة بدقة بُعد {dim}؛",
    "20638": "2. الملفات القديمة التي تم تحليلها: لن يتم التمثيل بالفهارس السيميائية القديمة، لكن للاستفادة من دقة المطابقة الحالية عند البحث، يجب تنفيذ خيار «إعادة التحليل» في قائمة الملفات.",
