    "20643": "حد أقصى لحجم استخراج المحتوى (يشمل OCR)",
    "20644": "أقصى حجم استخراج للمؤشر النصي الفردي (نص / مستند / OCR / HTML). سيتم اقتطاع المحتوى الطويل تلقائيًا. وإلا فإن ذلك سيؤدي إلى استهلاك كبير لمساحة التخزين مما يؤثر على الأداء.",
