    "20649": "يدعم تصدير الصفحة الأولى من مستندات Office كصورة مصغرة للغلاف، لكن هذا يزيد بشكل كبير من وقت استخراج محتوى Office، ولا يؤثر على ملفات PDF. يتطلب تثبيت LibreOffice.",
