    "20667": "تُقطع N ثوانٍ الأولى من الفيديو/الصود للنسخ الصوتي؛ الإعداد الكبير جدًا يمدد وقت التحليل وقد يؤدي إلى فشل بسبب انتهاء المهلة",
    "20668": "الاستعراف ومعالجة OCR",
    "20669": "تفعيل الاستعراف الذكي للصور عبر OCR",
    "20670": "استعراف ذكي بسرعة تقيس بالملي ثانية لتحديد وجود النص في الصور، وإذا كان موجوداً يتم استعرافه عبر OCR",
    "20671": "عدد عمليات استعراف OCR للملفات",
    "20672": "الحد الأقصى لعدد عمليات استعراف OCR للملفات (عدد الصور المدمجة داخل مستندات Office / عدد صفحات مستندات PDF)",
