    "20677": "OCR فائق السرعة",
    "20678": "إنجاز العمل خلال 1-2 ثوانٍ لكل صورة، مناسب لمعظم السيناريوهات",
    "20679": "OCR عالي الدقة",
    "20680": "إنجاز العمل خلال 2-4 ثوانٍ لكل صورة، لزيادة دقة التعرف",
    "20681": "إعادة استخدام البيانات أثناء إعادة التحليل",
    "20682": "إذا كانت هناك تحديثات للملفات، يرجى إلغاء تحديد هذا الخيار، وإلا فسيتم تخطي جمع معلومات هذا الخيار إذا كانت المعلومات الأساسية للملف موجودة بالفعل، وتشمل المعلومات الأساسية: نوع الملف، المصغرات، البيانات الوصفية، محتوى الملف",
    "20683": "تسريع عملية التحليل، لن يتم إعادة جمع معلومات مرحلة التحليل القياسية",
    "20684": "مثال: خصائص مجموعات الملفات كمجموعة وحدة: مجموعات ملفات بأسماء تحمل لاحقة رقمية، مثال: 1.txt, 2.txt, 3.txt",
    "20686": "تحديد الوحدات الكاملة مثل الملفات المتسلسلة، وبومات المسارات الصوتية، ومجلدات المشاريع، مع دعم تلميحات مخصصة لتحديد الوحدات",
    "20687": "تفعيل تحديد أصغر وحدة",
    "20688": "الفئات التالية تُحدد بشكل إجباري دون الحاجة للتفعيل: المجلدات النظامية، ومجلدات تثبيت البرامج، ومشاريع هندسية، وحزم الألعاب، ومجموعات بيانات/نماذج الذكاء الاصطناعي، وكاش مع LFS، والبيئات الافتراضية",
    "20689": "بعد التفعيل، يتم تجاوز التحليل الدقيق للـملفات للتُحدد كمجلدات بأصغر وحدة",
    "20690": "الملفات المتسلسلة: مستندات أو صور مرقمة تسلسلياً (مثل 01.jpg، 02.jpg، 03.jpg)",
    "20691": "البوم الصوتي: مجموعة من ملفات المسارات الصوتية من نفس الألبوم (مثل .flac، .mp3)",
    "20692": "مشروع التصميم: مشروع تصميم يتضمن ملفات المشاريع وموارد الأدلة (مثل .prproj، .aep، .blend)",
    "20693": "تنبيه: بعد الإيقاف، ستُحلَّل جميع الملفات بشكل مستقل، وهو مناسب للحالات التي تتطلب توليد أوصاف ووسوم بشكل منفرد لكل ملف",
    "20694": "كلمة التلميح لتحديد الحد الأدنى من الوحدات",
    "20695": "يتطلب تفعيل المفتاح أعلاه ليصبح فعالاً",
    "20696": "تحديد أي مجموعة ملفات يجب اعتبارها وحدة متكاملة، لضبط تحديد نموذج التوليف",
    "20697": "تتطلب الكلمات المفتاحية المخصصة للوحدة الدنيا محرك ذكاء اصطناعي متقدمًا قادرًا على فهم نماذج اللغة، وهو غير مفعَّل حاليًا.",
    "20698": "النظر في مفتاح أعلى الصفحة غير مفعَّل، ولا تُفعَّل الكلمات المفتاحية مؤقتًا.",
    "20699": "سيتم التعامل مع أي مجلد يُستخدَم كتعرف للوحدة الدنيا كملف واحد كامل، وذلك لتجنب توليد نتائج تحليل مفرقة بشكل مفرط.",
    "20700": "مطابقة مقاطع الفيديو الزمنية",
    "20701": "يتطلب تثبيت اعتماديات ffprobe الخارجية",
    "20702": "تنظيم الصفحة الرئيسية",
    "20703": "العودة إلى قائمة وظائف و نظرة شاملة على سير العمل",
    "20704": "التخطيط الأساسي للأرشفة وتخطيط فهرس AI",
    "20705": "تتبع الاسم الذكي للبيانات وصفق إعادة تسمية القوالب",
    "20706": "اختيار نقطة مجموعة لزيادة أو إزالة أبعاد وسمات الملف",
    "20707": "التمييز مزدوج المسار للملفات المكررة والمترادفة، مع حماية آمنة في سلة المحذوفات",
    "20708": "تنقل الوظائف بالجملة",
    "20709": "فتح الشريط الجانبي للوظائف",
    "20710": "طوي الشريط الجانبي للوظائف",
    "20711": "تنقل الوظائف",
    "20712": "المعالجة المسبقة",
    "20713": "أساسي",
    "20714": "معالجة مسبقة · تسمية",
    "20715": "معالجة مسبقة · وضع وسوم",
    "20716": "دعم الاختيار النقطي متعدد الأبعاد لإضافة وإزالة جماعية لوسوم الملفات المستهدفة، لإكمال الصورة الدلالية للملفات.",
    "20717": "فحص أمان النسخ المكررة",
    "20718": "يحلل FireFly Omni الذكي بأمان ويزيل الملفات المكررة الزائدة، مع نقل جميع الحذف إلى سلة النظام.",
    "20719": "اختيار سير عمل الترتيب الرئيسي أو المعالجة المسبقة",
    "20720": "يُنصح بالانتقال مباشرة إلى [الترتيب الجماعي] حيث يبني AI نظام المجلدات لك؛ أو اختيار الأدوات الفضائية قبل الترتيب لإعادة التسمية القياسية، أو إضافة علامات الوسم، أو تنظيف النسخ المكررة بأمان.",
    "20721": "سير عمل AI الرئيسي",
    "20722": "تخطيط ذكي شامل لمجلدات AI، مقارنة الخطط، وأرشفة الملفات",
    "20723": "ابدأ الترتيب الجماعي الآن",
    "20724": "بناءً على التحليل الذكي متعدد الأبعاد عبر الذكاء الاصطناعي أو قواعد الكتالوج الافتراضي، يُصنَّف الملفات المحددة بذكاء ويُستخرَجها إلى الكتالوجات المادية أو الكتالوجات الافتراضية الجديدة. بدون عمليات تمهيدية معقدة، يتم إنشاء مخطط ملفات عالي الكفاءة مباشرةً.",
    "20725": "تنظيم سريع ومباشر",
    "20726": "مقارنة عميقة وخيارات متعددة",
    "20727": "أرشفة في الكتالوجات الافتراضية والمادية",
    "20728": "أنقاذ تلقائي للمصنفات غير المُصنَّفة",
    "20729": "أدوات المعالجة المسبقة (وحدات أقمار صناعية ما قبل التنظيم)",
    "20730": "قبل التنظيم، قم بتوحيد أسماء الملفات أو وضع وسوم دقيقة في جميع الأبعاد أو استبعاد العناصر الزائدة، لتحسين نتائج التنظيم بشكل كبير",
    "20731": "الدخول إلى مساحة العمل",
    "20732": "العودة إلى صفحة الرئيسية للتنظيم، وعرض نظرة عامة على الوظائف والتبديل إلى مسارات أخرى",
